// sys_tenantCursorValues 提取用于构造 nextCursor 的排序列值,顺序与有效排序一致。
//
// 参数:
//   - row: 查询结果中的一行模型。
//   - seq: 排序列及方向,顺序与游标值顺序一致。
//
// 返回值:
//   - []any: 与 seq 一一对应的列值切片。
func sys_tenantCursorValues(row SysTenant, seq []dynq.SortField) []any {
	vals := make([]any, len(seq))
	for i, sf := range seq {
		switch sf.Key {
		case "id":
			vals[i] = row.ID
		case "status":
			vals[i] = row.Status
		case "name":
			vals[i] = row.Name
		case "expiredAt":
			vals[i] = row.ExpiredAt
		case "maxUserCount":
			vals[i] = row.MaxUserCount
		case "createdAt":
			vals[i] = row.CreatedAt
		case "updatedAt":
			vals[i] = row.UpdatedAt
		default:
			vals[i] = nil
		}
	}
	return vals
}

// ListSysTenant 按 params 的过滤、排序、投影与分页条件查询列表页。
// 返回本页行、是否还有下一页与续翻游标;total 由 CountSysTenant 单独计算
// (非强一致快照)。生成代码为纯函数,不持有连接状态。
// 未查询列在结果中留零值(动态投影固有语义),需区分时按请求 fields 做 DTO 化。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,可由 ParseSysTenantQuery 产出或直接构造。
//   - opts:   运行期能力收窄选项;禁用目标不在 registry 时返回错误。
//
// 返回值:
//   - dynq.Result[SysTenant]: 本页行、是否还有下一页与续翻游标。
//   - error:              查询或校验失败时的错误。
func ListSysTenant(ctx context.Context, db DBTX, params ListSysTenantParams, opts ...dynq.QueryOption) (dynq.Result[SysTenant], error) {
	cfg, err := dynq.NewQueryConfig(sys_tenantRegistry, opts...)
	if err != nil {
		return dynq.Result[SysTenant]{}, err
	}
	if err := validateSysTenantParams(params, cfg); err != nil {
		return dynq.Result[SysTenant]{}, err
	}
	limit, err := dynq.CheckPagination(sys_tenantRegistry, params.Limit, params.Offset, params.After)
	if err != nil {
		return dynq.Result[SysTenant]{}, err
	}
	// 解析有效排序:未指定排序时回落表级 @default_sort。
	seq, err := dynq.ResolveSort(sys_tenantRegistry, cfg, params.OrderBy)
	if err != nil {
		return dynq.Result[SysTenant]{}, err
	}
	fp := dynq.CursorFingerprint(sys_tenantRegistry.Resource, seq)
	// 计算 SELECT 列:投影列并集排序列(排序所需列始终参与查询)。
	cols := dynq.SelectColumns(sys_tenantRegistry, params.SelectFields, seq)
	b := sq.Select(cols...).From("sys_tenant").PlaceholderFormat(sq.Dollar).Where(sq.And(buildSysTenantWhere(params))).
		OrderBy(dynq.OrderBySQL(seq)).Limit(uint64(limit) + 1)
	// After 非 nil 时为游标模式:解码并校验游标,从该位置继续读取。
	if params.After != nil {
		vals, err := dynq.DecodeCursor(*params.After, fp, seq)
		if err != nil {
			return dynq.Result[SysTenant]{}, err
		}
		seek, err := dynq.SeekPredicate(seq, vals)
		if err != nil {
			return dynq.Result[SysTenant]{}, err
		}
		b = b.Where(seek)
	}
	if params.Offset > 0 {
		b = b.Offset(uint64(params.Offset))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return dynq.Result[SysTenant]{}, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return dynq.Result[SysTenant]{}, err
	}
	items, err := pgx.CollectRows(rows, pgx.RowToStructByNameLax[SysTenant])
	if err != nil {
		return dynq.Result[SysTenant]{}, err
	}
	// 以 LIMIT n+1 探测是否还有下一页,并构造 nextCursor。
	hasMore := len(items) > int(limit)
	if hasMore {
		items = items[:limit]
	}
	var next string
	if hasMore {
		next, err = dynq.EncodeCursor(fp, seq, sys_tenantCursorValues(items[len(items)-1], seq))
		if err != nil {
			return dynq.Result[SysTenant]{}, err
		}
	}
	return dynq.Result[SysTenant]{Items: items, HasMore: hasMore, NextCursor: next}, nil
}

// CountSysTenant 统计满足过滤条件的行数,与分页模式和游标位置无关;
// 忽略投影、排序与游标。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,与 ListSysTenant 使用同一份形态复核。
//   - opts:   运行期能力收窄选项。
//
// 返回值:
//   - int64: 满足过滤条件的行数。
//   - error: 查询或校验失败时返回错误。
func CountSysTenant(ctx context.Context, db DBTX, params ListSysTenantParams, opts ...dynq.QueryOption) (int64, error) {
	cfg, err := dynq.NewQueryConfig(sys_tenantRegistry, opts...)
	if err != nil {
		return 0, err
	}
	if err := validateSysTenantParams(params, cfg); err != nil {
		return 0, err
	}
	if _, err := dynq.CheckPagination(sys_tenantRegistry, params.Limit, params.Offset, params.After); err != nil {
		return 0, err
	}
	query, args, err := sq.Select("COUNT(*)").From("sys_tenant").PlaceholderFormat(sq.Dollar).Where(sq.And(buildSysTenantWhere(params))).ToSql()
	if err != nil {
		return 0, err
	}
	var total int64
	if err := db.QueryRow(ctx, query, args...).Scan(&total); err != nil {
		return 0, err
	}
	return total, nil
}

// SysTenantTable 是本表 Update 方法族的编译期 marker:选项类型按表绑定,
// 跨表误用(SET / WHERE 选项串表)在编译期被拒绝,而不是运行期报错。
type SysTenantTable struct{}

// SysTenantUpdate 是 Update 方法族的命名空间对象(如 SysTenantUpdate.SetName)。
// 取 XxxUpdate 而非表名单数:与 sqlc-gen-go 同包时模型类型已占用单数名
// (如 sys_user → SysUser),命名空间对象不能复用。
var SysTenantUpdate SysTenantTable

// SysTenantUpdateOption 是本表的更新选项别名。SET 资格面是列级 @updatable 的
// set-capable 形态;WHERE 资格面是 where-capable 形态,有 @pk 时自动附带
// 主键列的完整类型矩阵(定位方法)。两个能力面与 @dynamic / @scope 解耦。
type SysTenantUpdateOption = dynq.UpdateOption[SysTenantTable]

// ---- SET 白名单(set-capable @updatable 列;未调用的列保持原值)----

// SetStatus 设置 status（数据状态，0：禁用、1：启用）列值，无 nil。
